/**
 * @summary List pricing recommendations
 */
export const getListRecommendationsUrl = (
  params?: ListRecommendationsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/recommendations?${stringifiedParams}`
    : `/api/recommendations`;
};

export const listRecommendations = async (
  params?: ListRecommendationsParams,
  options?: RequestInit,
): Promise<RecommendationListResponse> => {
  return customFetch<RecommendationListResponse>(
    getListRecommendationsUrl(params),
    {
      ...options,
      method: "GET",
    },
  );
};

